package com.example.movietickets.controller;
import com.example.movietickets.dto.*; import com.example.movietickets.model.*; import com.example.movietickets.repository.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {
 private final MovieRepository movies; private final ShowtimeRepository showtimes; private final BookingRepository bookings; private final UserRepository users;
 public AdminController(MovieRepository movies,ShowtimeRepository showtimes,BookingRepository bookings,UserRepository users){this.movies=movies;this.showtimes=showtimes;this.bookings=bookings;this.users=users;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("movies",movies.findByActiveTrue().size(),"showtimes",showtimes.findAll().stream().filter(Showtime::isActive).count(),"bookings",bookings.count(),"customers",users.findAll().stream().filter(u->u.getRole()==User.Role.CUSTOMER).count());}
 @GetMapping("/movies") public List<Movie> allMovies(){return movies.findAll();}
 @PostMapping("/movies") public ResponseEntity<Movie> createMovie(@Valid @RequestBody MovieAdminRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(movies.save(new Movie(r.title(),r.genre(),r.durationMinutes(),r.description(),r.posterUrl(),r.rating(),r.featured())));}
 @PutMapping("/movies/{id}") public Movie updateMovie(@PathVariable Long id,@Valid @RequestBody MovieAdminRequest r){Movie m=movies.findById(id).orElseThrow();m.update(r.title(),r.genre(),r.durationMinutes(),r.description(),r.posterUrl(),r.rating(),r.featured());return movies.save(m);}
 @DeleteMapping("/movies/{id}") public Map<String,String> deleteMovie(@PathVariable Long id){Movie m=movies.findById(id).orElseThrow();m.setActive(false);movies.save(m);showtimes.findAll().stream().filter(s->s.getMovie().getId().equals(id)).forEach(s->{s.setActive(false);showtimes.save(s);});return Map.of("message","Movie archived and hidden from customers");}
 @Transactional(readOnly=true) @GetMapping("/showtimes") public List<Map<String,Object>> allShowtimes(){return showtimes.findAll().stream().sorted(Comparator.comparing(Showtime::getStartTime)).map(this::showtimeView).toList();}
 @PostMapping("/showtimes") public ResponseEntity<Showtime> createShowtime(@Valid @RequestBody ShowtimeAdminRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(showtimes.save(buildShowtime(r)));}
 @PutMapping("/showtimes/{id}") public Showtime updateShowtime(@PathVariable Long id,@Valid @RequestBody ShowtimeAdminRequest r){Showtime s=showtimes.findById(id).orElseThrow();s.update(movies.findById(r.movieId()).orElseThrow(),r.startTime(),r.screenName(),r.format(),r.formatSurcharge(),r.classicPrice(),r.premiumPrice(),r.reclinerPrice());return showtimes.save(s);}
 @DeleteMapping("/showtimes/{id}") public Map<String,String> deleteShowtime(@PathVariable Long id){Showtime s=showtimes.findById(id).orElseThrow();s.setActive(false);showtimes.save(s);return Map.of("message","Showtime archived and hidden from customers");}
 private Showtime buildShowtime(ShowtimeAdminRequest r){Showtime s=new Showtime(movies.findById(r.movieId()).orElseThrow(),r.startTime(),r.screenName(),r.classicPrice()+r.formatSurcharge());s.update(s.getMovie(),r.startTime(),r.screenName(),r.format(),r.formatSurcharge(),r.classicPrice(),r.premiumPrice(),r.reclinerPrice());return s;}
 private Map<String,Object> showtimeView(Showtime s){Map<String,Object> v=new LinkedHashMap<>();v.put("id",s.getId());v.put("movieId",s.getMovie().getId());v.put("movieTitle",s.getMovie().getTitle());v.put("startTime",s.getStartTime());v.put("screenName",s.getScreenName());v.put("format",s.getFormat());v.put("formatSurcharge",s.getFormatSurcharge());v.put("classicPrice",s.getClassicPrice());v.put("premiumPrice",s.getPremiumPrice());v.put("reclinerPrice",s.getReclinerPrice());v.put("active",s.isActive());return v;}
}
